import{_ as t,o,c as i,a6 as r}from"./chunks/framework.CKIbuWFA.js";const v=JSON.parse('{"title":"Développer TikTools","description":"","frontmatter":{"title":"Développer TikTools","docId":"developer.overview","translationKey":"developer.overview","locale":"fr","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"1ee65a70172f8154eeaf60fb1a3069192769582a4ef264426d0aefaf346e8003","translationRevision":"3ac934adcd87c9b49562e98a054d0f77254308641551707e63ddbab94d483e89","order":0},"headers":[],"relativePath":"fr/developer/index.md","filePath":"fr/developer/index.md","lastUpdated":1794611623000}'),a={name:"fr/developer/index.md"};function s(n,e,d,l,c,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="develop-tiktools" tabindex="-1">Développer TikTools <a class="header-anchor" href="#develop-tiktools" aria-label="Permalink to &quot;Développer TikTools {#develop-tiktools}&quot;">​</a></h1><p>TikTools conserve un seul AppCore natif derrière des opérations de contrôle typées. Vue affiche les interfaces de bureau, de navigateur local et de contrôleur ; Winit/Wry possède les fenêtres de bureau. La CLI et le SDK utilisent les mêmes opérations. Commencez par la <a href="./setup.html">configuration de développement</a>, puis choisissez la boucle la plus courte couvrant votre modification.</p><h2 id="choose-an-entry-point" tabindex="-1">Choisir un point d’entrée <a class="header-anchor" href="#choose-an-entry-point" aria-label="Permalink to &quot;Choisir un point d’entrée {#choose-an-entry-point}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Travail</th><th>Point d’entrée</th><th>Ce qu’il permet de vérifier</th></tr></thead><tbody><tr><td>Composants et stores Vue</td><td>Vite, Vitest et ControlClient injecté</td><td>Comportement de l’interface ; aucune validation de fenêtre native.</td></tr><tr><td>Intégration de bureau</td><td><code>bun run start</code></td><td>Intégration WebView et IPC de développement.</td></tr><tr><td>Services natifs</td><td>Tests Cargo ciblés</td><td>Contrats du cœur, persistance et comportement des services.</td></tr><tr><td>Accès navigateur sans interface native</td><td><code>bun run dev</code></td><td>Un hôte natif, un adaptateur local et Vite avec appairage.</td></tr><tr><td>Documentation</td><td><code>bun scripts/task.ts docs dev</code></td><td>Markdown et compilation VitePress isolée.</td></tr><tr><td>Démo publique</td><td>Entrée de démo distincte et transport simulé</td><td>Scénarios fictifs déterministes, pas les services distants.</td></tr></tbody></table><h2 id="source-ownership" tabindex="-1">Responsabilité du code source <a class="header-anchor" href="#source-ownership" aria-label="Permalink to &quot;Responsabilité du code source {#source-ownership}&quot;">​</a></h2><ul><li><code>crates/tiktools-core</code> : services, opérations et SQLite. Il ne dépend pas d’une WebView.</li><li><code>crates/tiktools-control-api</code> : registre, routage JSON-RPC, IPC et découverte.</li><li><code>crates/tiktools-desktop</code> : Winit/Wry, pont du thread d’interface, cycle de vie et ressources empaquetées.</li><li><code>src/web/app</code> : initialisation, routeur et structure de l’interface. <code>pages</code> compose <code>widgets</code> et <code>features</code> ; <code>entities</code> possède les stores/contrats métier ; <code>shared</code> contient l’interface réutilisable et l’infrastructure.</li><li><code>src/automation/contracts/generated</code> : contrats d’événements versionnés de l’interface, générés depuis Rust. Ne ressaisissez pas ces schémas dans une démo ou un guide.</li><li><code>packages</code> : paquets TypeScript existants du SDK et de l’interface des plugins. Les implémentations des plugins se trouvent dans le dépôt externe de plugins.</li></ul><h2 id="contribution-boundary" tabindex="-1">Limites des contributions <a class="header-anchor" href="#contribution-boundary" aria-label="Permalink to &quot;Limites des contributions {#contribution-boundary}&quot;">​</a></h2><p>Gardez explicites les points d’entrée natif, navigateur local, contrôleur distant et démo. L’absence d’hôte natif est une erreur dans un vrai point d’entrée ; elle ne doit pas sélectionner silencieusement un simulacre. Libérez écouteurs, abonnements et temporisateurs avec leur portée propriétaire. Préservez les fichiers de verrouillage Rust/Bun et les contrôles CI requis.</p><p>L’installation utilisateur relève du <a href="./../user/installation.html">guide d’utilisation</a>. Ces vérifications de développement n’établissent pas à elles seules la connectivité réelle TikTok, le rendu OBS, la compatibilité WebView native ou la collaboration entre deux ordinateurs.</p>',9)])])}const f=t(a,[["render",s]]);export{v as __pageData,f as default};
